fn is_prime(n: i8) -> bool {
    // Check for numbers less than 2
    if n < 2 {
        return false;
    }

    // Check for divisors from 2 to n-1
    for divisor in 2..n {
        if n % divisor == 0 {
            return false; // Found a divisor, not prime
        }
    }

    // If no divisors were found, it is prime
    true
}